import * as E from './engine.js';
import {originalTiles} from './world.js';
import {GAME} from './config.js';
export function territoryPanel(s,h){const {panelHead,fmt}=h,w=s.world;return panelHead('ARCHIPIÉLAGO · 100 × 100','Extiende tu base.')+'<p>Posees '+w.owned.length+' de 72 sectores disponibles. Cada sector mide 10 × 10 casillas. Los 28 restantes pertenecen a escenarios enemigos.</p><div class="sector-map" aria-label="Sectores del archipiélago">'+Array.from({length:100},(_,i)=>{const id=i+1,owned=w.owned.includes(id),q=E.expansionQuote(s,id),x=i%10*2,y=Math.floor(i/10)*2,tiles=originalTiles(w.layout),land=[tiles[y][x],tiles[y][x+1],tiles[y+1][x],tiles[y+1][x+1]].some(v=>v!==0);return'<button data-action="sector" data-index="'+id+'" class="'+(owned?'owned':id>72?'reserved':q.ok?'available':'')+(land?' land':' sea')+'" aria-label="Sector '+id+(owned?', propio':id>72?', enemigo':q.ok?', ampliar por '+q.cost.gold+' oro':', sin conexión')+'">'+id+'</button>';}).join('')+'</div><p class="tiny">Verde: propio · dorado: ampliable · rojo: reservado. Puedes acercar la cámara a cualquier sector.</p><button class="primary wide" data-action="expand-mode">Marcar ampliaciones en el mapa</button><button class="wide" data-action="overview">Ver archipiélago completo</button><p>La próxima ampliación cuesta '+fmt(E.expansionQuote(s,1).cost.gold)+' de oro. Une las orillas con puentes para abrir rutas terrestres. Los astilleros necesitan una costa.</p><div class="section-label">UNA BASE DESARROLLADA</div><p>Prueba todas las instalaciones y unidades en una base de demostración independiente.</p><button class="wide" data-action="advanced-demo">Visitar base avanzada</button>';}
export function industryPanel(s,b,h){const {fmt,clock}=h;if(!E.isFactory(b.type))return'';const p=b.production,working=p?.status==='working';return'<div class="section-label">PROGRAMAR PRODUCCIÓN</div><p class="tiny">Elige un lote y recógelo al terminar. Los ciclos originales son 5 min, 1 h, 4 h y 8 h; fácil acelera ×10 y difícil ×3. Simulación conserva su duración.</p>'+(working?'<div class="warning">'+fmt(p.amount)+' en proceso · '+clock(p.ends-s.time)+'</div><div class="progress"><span style="width:'+Math.min(100,(s.time-p.started)/(p.ends-p.started)*100)+'%"></span></div>':'')+'<div class="cycle-options">'+E.productionOptions.map(o=>{const q=E.productionQuote(s,b,o.index);return'<button data-action="produce" data-id="'+b.id+'" data-index="'+o.index+'" '+(working||b.stored>=1||b.job||b.hp<=0?'disabled':'')+'><b>'+fmt(q.amount)+' '+GAME.resources[E.BUILDINGS[b.type].resource].name.toLowerCase()+'</b><small>'+clock(q.duration)+' · ciclo '+o.minutes+' min</small></button>';}).join('')+'</div>'+(b.stored>=1?'<p class="tiny">Recoge el lote pendiente para encargar otro.</p>':'');}
export function marketPanel(s,b){if(b.type!=='market')return'';return'<div class="section-label">INTERCAMBIO DE MATERIALES</div><p class="tiny">Lotes de 100. Madera y petróleo: compra 100 oro, venta 75. Acero: compra 150, venta 113. Máximo 20 operaciones cada 20 horas.</p>'+['wood','supply','metal'].map(type=>'<div class="stat-row"><span>'+GAME.resources[type].name+'</span><button data-action="trade-buy" data-type="'+type+'">Comprar</button><button data-action="trade-sell" data-type="'+type+'">Vender</button></div>').join('')+'<p class="tiny">Operaciones usadas: '+(s.world.market&&s.time-s.world.market.started<72000?s.world.market.used:0)+' / 20</p>';}
export function specialInspector(s,selected,h){const {img,icon,clock,cost,fmt}=h,bridge=s.world?.bridges.find(b=>'bridge:'+b.id===selected[0]),army=s.army.filter(u=>selected.includes(u.id));if(bridge){const q=E.bridgeQuote(s,bridge.x,bridge.y,bridge.id);return'<div class="panel-top"><h2>Puente '+(bridge.broken?'interrumpido':'operativo')+'</h2><button class="close" data-action="deselect" aria-label="Cerrar puente">'+icon('close')+'</button></div>'+img(bridge.broken?'ruinedBridge':'bridge')+'<p>Conecta dos orillas. Las tropas terrestres y los obreros pueden cruzarlo una vez terminado. Los barcos navegan por el agua.</p>'+(bridge.job?'<p class="warning">Reparando · '+clock(bridge.job.ends-s.time)+'</p>':bridge.broken?cost(q.cost)+'<button class="primary wide" data-action="repair-bridge" data-id="'+bridge.id+'" '+(!q.ok?'disabled':'')+'>Restaurar el paso</button><p class="tiny">'+(q.message||'Requiere una cuadrilla durante 60 segundos.')+'</p>':'<p>Ruta terrestre abierta.</p>');}if(!army.length)return null;const u=army[0],spec=E.UNITS[u.type];return'<div class="panel-top"><div><div class="eyebrow">EJÉRCITO EN LA BASE</div><h2>'+(army.length===1?spec.name:army.length+' unidades')+'</h2></div><button class="close" data-action="deselect" aria-label="Cerrar tropas">'+icon('close')+'</button></div>'+img(u.type,u.level,true,'hero-image')+'<p>Toca un destino libre para mover la selección. Arrastra un rectángulo para formar un grupo. Los vehículos respetan el agua y los edificios; las aeronaves vuelan y los barcos permanecen en el mar.</p><div class="stat-row"><span>Integridad</span><strong>'+fmt(army.reduce((v,u)=>v+u.hp,0))+'</strong></div><button class="wide" data-action="home-select-all">Seleccionar ejército</button><button class="wide" data-action="home-hold">Detener selección</button>';}
